def ensure_embedding_model_local(self) -> dict[str, object]:
        """Prime the configured embedding model cache and return local cache details."""
        backend = self._ensure_embedding_backend()
        # Trigger a real embedding pass so missing model weights are downloaded eagerly.
        backend.embed_texts(["vector-index-bootstrap"])
        model_cache_path = embedding_model_cache_path(self.embedding_cache_dir, backend.model_name)
        if not model_cache_path.exists():
            fallback_candidates = sorted(self.embedding_cache_dir.glob("models--*"))
            if fallback_candidates:
                model_cache_path = fallback_candidates[0]
        return {
            "embedding_model": backend.model_name,
            "embedding_cache_dir": str(self.embedding_cache_dir),
            "embedding_model_cache_path": str(model_cache_path),
            "embedding_model_cache_present": model_cache_path.exists(),
        }

def _ensure_embedding_backend(self) -> _FastEmbedBackend:
        if self._embedding_backend is None:
            self._embedding_backend = _FastEmbedBackend(
                self.embedding_model,
                cache_dir=self.embedding_cache_dir,
            )
        return self._embedding_backend

def __init__(self, model_name: str, *, cache_dir: Path) -> None:
        if TextEmbedding is None:
            raise RuntimeError(
                "fastembed is required for the vector index; run `uv sync` after adding the dependency."
            )
        self._model_name = model_name
        cache_dir.mkdir(parents=True, exist_ok=True)
        self._model = TextEmbedding(model_name=model_name, cache_dir=str(cache_dir))

class _FastEmbedBackend:
    """Thin wrapper around fastembed so the store can own embedding lifecycle."""

    def __init__(self, model_name: str, *, cache_dir: Path) -> None:
        if TextEmbedding is None:
            raise RuntimeError(
                "fastembed is required for the vector index; run `uv sync` after adding the dependency."
            )
        self._model_name = model_name
        cache_dir.mkdir(parents=True, exist_ok=True)
        self._model = TextEmbedding(model_name=model_name, cache_dir=str(cache_dir))

    @property
    def model_name(self) -> str:
        return self._model_name

    def embed_texts(self, texts: Sequence[str]) -> list[list[float]]:
        vectors = list(self._model.embed(list(texts)))
        return [[float(value) for value in vector] for vector in vectors]

class _PendingRefreshBuffer:
    """Collect file paths until the watcher has been quiet long enough."""

    def __init__(self, service, repo_root: Path, *, revision: str) -> None:
        self._service = service
        self._repo_root = repo_root.expanduser().resolve()
        self._revision = revision
        self._pending_paths: set[Path] = set()
        self._lock = threading.Lock()

    def add(self, raw_path: str | Path) -> None:
        candidate = Path(raw_path)
        if should_skip_path(candidate, self._repo_root):
            return

        if not candidate.is_absolute():
            candidate = (self._repo_root / candidate).resolve()
        else:
            candidate = candidate.resolve()

        if candidate.suffix.lower() not in _WATCHABLE_SUFFIXES:
            return

        with self._lock:
            self._pending_paths.add(candidate)

    def flush(self):
        with self._lock:
            if not self._pending_paths:
                return None
            changed_paths = sorted(self._pending_paths)
            self._pending_paths.clear()
        return self._service.refresh_changed_files(changed_paths, revision=self._revision)

def _vector_trust_decision(
    scope_path: Path,
    *,
    request_is_scoped: bool | None = None,
) -> _VectorTrustDecision:
    """Return the explicit trust outcome for one read request."""
    probe = _load_vector_probe_cache(_read_code_session_id())
    if probe is None:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state="recover",
            runtime_note="vector trust invalidated: no cached probe available",
        )
    if request_is_scoped is False:
        if probe.status == "healthy":
            return _VectorTrustDecision(trusted=True, trust_state="reused", escalation_state="none")
        if probe.status in {"missing", "unavailable", "probe-failed"}:
            return _VectorTrustDecision(
                trusted=False,
                trust_state="invalidated",
                escalation_state=probe.escalation_state,
                runtime_note=f"vector trust invalidated: status is {probe.status}",
            )
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state=probe.escalation_state,
            runtime_note="vector trust invalidated: broad read requires recovery",
        )
    if request_is_scoped is not True:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state="unknown",
            runtime_note="vector trust invalidated: request scope unavailable",
        )
    if probe.status in {"missing", "unavailable", "probe-failed"}:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state=probe.escalation_state,
            runtime_note=f"vector trust invalidated: status is {probe.status}",
        )
    if probe.status == "healthy":
        return _VectorTrustDecision(trusted=True, trust_state="reused", escalation_state="none")
    if probe.status != "stale":
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state="unknown",
            runtime_note=f"vector trust invalidated: status is {probe.status}",
        )
    overlap = _scope_needs_vector_refresh(scope_path, probe.stale_drift_paths)
    if overlap is False:
        return _VectorTrustDecision(trusted=True, trust_state="reused", escalation_state="none")
    if overlap is True:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state=probe.escalation_state,
            runtime_note="vector trust invalidated: stale drift overlaps requested scope",
        )
    return _VectorTrustDecision(
        trusted=False,
        trust_state="invalidated",
        escalation_state=probe.escalation_state,
        runtime_note="vector trust invalidated: stale overlap unknown",
    )

def evaluate_read_vector_trust(scope_path: Path, *, request_is_scoped: bool | None = None) -> bool:
    """Return whether a read can trust cached vector freshness for the requested scope."""
    decision = _vector_trust_decision(scope_path, request_is_scoped=request_is_scoped)
    if decision.runtime_note:
        _set_vector_runtime_note(decision.runtime_note)
    return decision.trusted

def _vector_probe_state(status: str) -> tuple[str, str]:
    """Return coarse trust and escalation labels for a probe status."""
    if status == "healthy":
        return "reused", "none"
    if status == "stale":
        return "invalidated", "refresh"
    if status == "missing":
        return "invalidated", "bootstrap"
    if status in {"unavailable", "probe-failed"}:
        return "invalidated", "recover"
    return "unknown", "unknown"

def _read_request_trusts_vector_cache(scope_path: Path, *, request_is_scoped: bool | None = None) -> bool:
    """Return whether a read can skip the heavyweight vector refresh path."""
    probe = _load_vector_probe_cache(_read_code_session_id())
    if probe is None:
        return False
    if request_is_scoped is False:
        return probe.status == "healthy"
    if request_is_scoped is not True:
        return False
    if probe.status in {"missing", "unavailable", "probe-failed"}:
        return False
    if probe.status == "healthy":
        return True
    if probe.status != "stale":
        return False
    return _scope_needs_vector_refresh(scope_path, probe.stale_drift_paths) is False

