def _parse_daemon_args(argv: list[str]) -> _DaemonArgs | None:
    """Parse read_code daemon commands for status, start, stop, and log inspection."""
    if not argv:
        print("ERROR: daemon mode requires a command (status | start | stop | logs)", file=sys.stderr)
        return None
    command = argv[0]
    if command not in {"status", "start", "stop", "logs"}:
        print(f"ERROR: Unknown daemon command '{command}'. Use: status | start | stop | logs", file=sys.stderr)
        return None
    if command == "status":
        if len(argv) != 1:
            print("ERROR: daemon status does not accept extra arguments", file=sys.stderr)
            return None
        return _DaemonArgs(command=command)
    if command == "stop":
        if len(argv) != 1:
            print("ERROR: daemon stop does not accept extra arguments", file=sys.stderr)
            return None
        return _DaemonArgs(command=command)
    if command == "start":
        force = False
        for token in argv[1:]:
            if token == "--force":
                force = True
                continue
            print(f"ERROR: Unknown daemon start argument '{token}'", file=sys.stderr)
            return None
        return _DaemonArgs(command=command, force=force)
    limit = 40
    if len(argv) > 2:
        print("ERROR: daemon logs accepts at most one optional line limit", file=sys.stderr)
        return None
    if len(argv) == 2:
        limit_raw = argv[1]
        if not limit_raw.isdigit() or int(limit_raw, 10) <= 0:
            print(f"ERROR: daemon logs limit must be a positive integer: {limit_raw}", file=sys.stderr)
            return None
        limit = min(int(limit_raw, 10), 200)
    return _DaemonArgs(command=command, limit=limit)

