def _select_vector_candidate(candidates: list[_VectorMatch], index: int) -> tuple[_VectorMatch | None, str | None]:
    """Select a ranked candidate index while returning actionable selection errors."""
    if index < 0:
        return None, f"candidate index must be >= 0: {index}"
    if not candidates:
        if index == 0:
            return None, None
        return None, "no ranked candidates available for requested candidate index"
    if index >= len(candidates):
        return None, f"candidate index {index} is out of range (available: 0..{len(candidates) - 1})"
    return candidates[index], None

def _vector_trust_decision(
    scope_path: Path,
    *,
    request_is_scoped: bool | None = None,
) -> _VectorTrustDecision:
    """Return the explicit trust outcome for one read request."""
    probe = _load_vector_probe_cache(_read_code_session_id())
    if probe is None:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state="recover",
            runtime_note="vector trust invalidated: no cached probe available",
        )
    if request_is_scoped is False:
        if probe.status == "healthy":
            return _VectorTrustDecision(trusted=True, trust_state="reused", escalation_state="none")
        if probe.status in {"missing", "unavailable", "probe-failed"}:
            return _VectorTrustDecision(
                trusted=False,
                trust_state="invalidated",
                escalation_state=probe.escalation_state,
                runtime_note=f"vector trust invalidated: status is {probe.status}",
            )
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state=probe.escalation_state,
            runtime_note="vector trust invalidated: broad read requires recovery",
        )
    if request_is_scoped is not True:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state="unknown",
            runtime_note="vector trust invalidated: request scope unavailable",
        )
    if probe.status in {"missing", "unavailable", "probe-failed"}:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state=probe.escalation_state,
            runtime_note=f"vector trust invalidated: status is {probe.status}",
        )
    if probe.status == "healthy":
        return _VectorTrustDecision(trusted=True, trust_state="reused", escalation_state="none")
    if probe.status != "stale":
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state="unknown",
            runtime_note=f"vector trust invalidated: status is {probe.status}",
        )
    overlap = _scope_needs_vector_refresh(scope_path, probe.stale_drift_paths)
    if overlap is False:
        return _VectorTrustDecision(trusted=True, trust_state="reused", escalation_state="none")
    if overlap is True:
        return _VectorTrustDecision(
            trusted=False,
            trust_state="invalidated",
            escalation_state=probe.escalation_state,
            runtime_note="vector trust invalidated: stale drift overlaps requested scope",
        )
    return _VectorTrustDecision(
        trusted=False,
        trust_state="invalidated",
        escalation_state=probe.escalation_state,
        runtime_note="vector trust invalidated: stale overlap unknown",
    )

def evaluate_read_vector_trust(scope_path: Path, *, request_is_scoped: bool | None = None) -> bool:
    """Return whether a read can trust cached vector freshness for the requested scope."""
    decision = _vector_trust_decision(scope_path, request_is_scoped=request_is_scoped)
    if decision.runtime_note:
        _set_vector_runtime_note(decision.runtime_note)
    return decision.trusted

def _read_request_trusts_vector_cache(scope_path: Path, *, request_is_scoped: bool | None = None) -> bool:
    """Return whether a read can skip the heavyweight vector refresh path."""
    probe = _load_vector_probe_cache(_read_code_session_id())
    if probe is None:
        return False
    if request_is_scoped is False:
        return probe.status == "healthy"
    if request_is_scoped is not True:
        return False
    if probe.status in {"missing", "unavailable", "probe-failed"}:
        return False
    if probe.status == "healthy":
        return True
    if probe.status != "stale":
        return False
    return _scope_needs_vector_refresh(scope_path, probe.stale_drift_paths) is False

def _vector_probe_state(status: str) -> tuple[str, str]:
    """Return coarse trust and escalation labels for a probe status."""
    if status == "healthy":
        return "reused", "none"
    if status == "stale":
        return "invalidated", "refresh"
    if status == "missing":
        return "invalidated", "bootstrap"
    if status in {"unavailable", "probe-failed"}:
        return "invalidated", "recover"
    return "unknown", "unknown"

def rerank_scores(self, query: str, passages: Sequence[str]) -> dict[str, object]:
        """Return local reranker scores for one query over a bounded passage window."""
        backend = self._ensure_reranker_backend()
        return {
            "model_name": backend.model_name,
            "scores": backend.rerank_scores(query, passages),
        }

    @property
def model_name(self) -> str:
        """Return the resolved reranker model name."""
        return self._model_name

def _parse_daemon_args(argv: list[str]) -> _DaemonArgs | None:
    """Parse read_code daemon commands for status, start, stop, and log inspection."""
    if not argv:
        print("ERROR: daemon mode requires a command (status | start | stop | logs)", file=sys.stderr)
        return None
    command = argv[0]
    if command not in {"status", "start", "stop", "logs"}:
        print(f"ERROR: Unknown daemon command '{command}'. Use: status | start | stop | logs", file=sys.stderr)
        return None
    if command == "status":
        if len(argv) != 1:
            print("ERROR: daemon status does not accept extra arguments", file=sys.stderr)
            return None
        return _DaemonArgs(command=command)
    if command == "stop":
        if len(argv) != 1:
            print("ERROR: daemon stop does not accept extra arguments", file=sys.stderr)
            return None
        return _DaemonArgs(command=command)
    if command == "start":
        force = False
        for token in argv[1:]:
            if token == "--force":
                force = True
                continue
            print(f"ERROR: Unknown daemon start argument '{token}'", file=sys.stderr)
            return None
        return _DaemonArgs(command=command, force=force)
    limit = 40
    if len(argv) > 2:
        print("ERROR: daemon logs accepts at most one optional line limit", file=sys.stderr)
        return None
    if len(argv) == 2:
        limit_raw = argv[1]
        if not limit_raw.isdigit() or int(limit_raw, 10) <= 0:
            print(f"ERROR: daemon logs limit must be a positive integer: {limit_raw}", file=sys.stderr)
            return None
        limit = min(int(limit_raw, 10), 200)
    return _DaemonArgs(command=command, limit=limit)

def _read_code_search_scratchpad_path(session_id: str) -> Path:
    """Return session-scoped scratchpad path for read_code search result reuse."""
