def ensure_embedding_model_local(self) -> dict[str, object]:
        """Prime the configured embedding model cache and return local cache details."""
        backend = self._ensure_embedding_backend()
        # Trigger a real embedding pass so missing model weights are downloaded eagerly.
        backend.embed_texts(["vector-index-bootstrap"])
        model_cache_path = embedding_model_cache_path(self.embedding_cache_dir, backend.model_name)
        if not model_cache_path.exists():
            fallback_candidates = sorted(self.embedding_cache_dir.glob("models--*"))
            if fallback_candidates:
                model_cache_path = fallback_candidates[0]
        return {
            "embedding_model": backend.model_name,
            "embedding_cache_dir": str(self.embedding_cache_dir),
            "embedding_model_cache_path": str(model_cache_path),
            "embedding_model_cache_present": model_cache_path.exists(),
        }

def _ensure_embedding_backend(self) -> _FastEmbedBackend:
        if self._embedding_backend is None:
            self._embedding_backend = _FastEmbedBackend(
                self.embedding_model,
                cache_dir=self.embedding_cache_dir,
            )
        return self._embedding_backend

def _read_cached_embedding_model_availability(root: Path) -> tuple[bool, str] | None:
    """Return a cached availability result when the embedding cache state matches."""
    cache_path = _embedding_model_availability_cache_path(root)
    if not cache_path.exists():
        return None

    try:
        payload = json.loads(cache_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None

    if not isinstance(payload, dict):
        return None
    if payload.get("version") != EMBEDDING_AVAILABILITY_CACHE_VERSION:
        return None
    if payload.get("model_name") != DEFAULT_EMBEDDING_MODEL_NAME:
        return None

    cache_exists, cache_mtime_ns = _embedding_model_cache_signature(root)
    if payload.get("cache_dir_exists") != cache_exists:
        return None
    if payload.get("cache_dir_mtime_ns") != cache_mtime_ns:
        return None

    available = payload.get("available")
    details = payload.get("details", "")
    if not isinstance(available, bool):
        return None
    if not isinstance(details, str):
        details = ""
    return available, details

def _health(self) -> dict[str, object] | None:
        """Return a healthy daemon payload when the socket endpoint is ready."""
        try:
            with self._http_client(timeout=READ_CODE_RERANKER_DAEMON_HEALTH_TIMEOUT_SECONDS) as client:
                response = client.get("/health")
                response.raise_for_status()
                payload = response.json()
        except (httpx.HTTPError, ValueError):
            return None
        if not isinstance(payload, dict):
            return None
        if payload.get("status") != "healthy":
            return None
        if payload.get("build_fingerprint") != self._build_fingerprint:
            return None
        if payload.get("model_name") != self._model_name:
            return None
        if payload.get("model_loaded") is not True:
            return None
        return payload

def _vector_query_candidates(
    file_path: Path | None,
    query: str,
    normalized_query: str,
    scope: str,
    *,
    allow_test_files: bool = False,
) -> list[_VectorMatch]:
    """Return the initial semantic retrieval window for one query scope."""
    if not query or not scope:
        return []
    if not _command_exists("uv"):
        _set_vector_runtime_note("uv is not available")
        return []

    cmd = _vector_indexer_cmd(
        REPO_ROOT,
        "query",
        query,
        "--scope",
        scope,
        "--top-k",
        "20",
    )
    if file_path is not None:
        cmd = _vector_indexer_cmd(
            REPO_ROOT,
            "query",
            query,
            "--file-path",
            str(file_path.resolve()),
            "--scope",
            scope,
            "--top-k",
            "20",
        )
    proc = _run_command_capture(cmd, env=_vector_command_env())
    if proc.returncode != 0:
        stderr = (proc.stderr or "").strip()
        if stderr:
            _set_vector_runtime_note(f"indexer query failed: {stderr.splitlines()[0]}")
        else:
            _set_vector_runtime_note(f"indexer query failed with exit code {proc.returncode}")
        return []

    try:
        payload = json.loads(proc.stdout or "[]")
    except json.JSONDecodeError:
        _set_vector_runtime_note("indexer query returned invalid JSON")
        return []
    if not isinstance(payload, list):
        _set_vector_runtime_note("indexer query returned unexpected payload shape")
        return []

    target = file_path.resolve() if file_path is not None else None
    matches: list[_VectorMatch] = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        candidate = _candidate_text(item, "file_path")
        if not candidate:
            continue
        if target is not None:
            try:
                if Path(candidate).expanduser().resolve() != target:
                    continue
            except Exception:
                continue
        match = _vector_match_for_item(item, query, normalized_query)
        if match is None:
            continue
        matches.append(match)

    return sorted(
        matches,
        key=lambda match: _vector_anchor_rank(match, allow_test_files=allow_test_files),
        reverse=True,
    )[:READ_CODE_RERANK_CANDIDATE_LIMIT]

def _load_read_code_reranker() -> _ReadCodeRerankerBackend | None:
    """Return the shared daemon-backed reranker client for this read_code process."""
    global _READ_CODE_RERANKER_BACKEND
    if _READ_CODE_RERANKER_BACKEND is None:
        _READ_CODE_RERANKER_BACKEND = _ReadCodeRerankerBackend(
